package io.invenlio.procurement;
import java.util.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.testcontainers.service.connection.ServiceConnection;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.context.ActiveProfiles;import org.springframework.test.web.servlet.*;import org.testcontainers.junit.jupiter.*;import org.testcontainers.postgresql.PostgreSQLContainer;import static org.junit.jupiter.api.Assertions.*;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.jwt;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@Testcontainers@SpringBootTest@AutoConfigureMockMvc@ActiveProfiles("test")class ProcurementIntegrationTest{static final UUID T=UUID.fromString("11111111-1111-4111-8111-111111111111"),V=UUID.fromString("30000000-0000-4000-8000-000000000002");@Container@ServiceConnection static final PostgreSQLContainer DB=new PostgreSQLContainer("postgres:17.6-alpine");@Autowired JdbcTemplate db;@Autowired MockMvc mvc;
 @BeforeEach void seed(){db.execute("TRUNCATE supplier_products,supplier_contacts,supplier_addresses,suppliers,inventory_reservation_allocations,inventory_reservations,inventory_ledger_entries,inventory_movements,inventory_balances,inventory_serials,inventory_lots CASCADE");db.update("DELETE FROM catalog_barcodes");db.update("DELETE FROM catalog_product_variants");db.update("DELETE FROM catalog_products");db.update("DELETE FROM audit_events");db.update("DELETE FROM membership_roles");db.update("DELETE FROM role_permissions");db.update("DELETE FROM organization_memberships");db.update("DELETE FROM roles");db.update("DELETE FROM user_identities");db.update("DELETE FROM organizations");UUID u=UUID.randomUUID(),m=UUID.randomUUID(),r=UUID.randomUUID(),p=UUID.randomUUID();db.update("INSERT INTO organizations(id,name,slug,status,default_locale,default_timezone,default_currency,created_at,updated_at,version)VALUES(?,?,?,'ACTIVE','en','UTC','EUR',now(),now(),0)",T,"T","t");db.update("INSERT INTO user_identities(id,keycloak_subject,status,created_at,updated_at)VALUES(?,?,'ACTIVE',now(),now())",u,"admin");db.update("INSERT INTO organization_memberships(id,tenant_id,user_identity_id,status,created_at,updated_at,version)VALUES(?,?,?,'ACTIVE',now(),now(),0)",m,T,u);db.update("INSERT INTO roles(id,tenant_id,name,system_role,created_at,updated_at,version)VALUES(?,?,?,false,now(),now(),0)",r,T,"PROC");for(String permission:List.of("procurement-supplier:read","procurement-supplier:manage"))db.update("INSERT INTO role_permissions VALUES(?,?,?)",T,r,permission);db.update("INSERT INTO membership_roles VALUES(?,?,?)",T,m,r);db.update("INSERT INTO catalog_products(id,tenant_id,name,status,base_unit,created_at,updated_at,version)VALUES(?,?,?,'ACTIVE','EA',now(),now(),0)",p,T,"Product");db.update("INSERT INTO catalog_product_variants(id,tenant_id,product_id,sku,normalized_sku,status,base_unit,option_signature,created_at,updated_at,version)VALUES(?,?,?,?,?,'ACTIVE','EA','DEFAULT',now(),now(),0)",V,T,p,"SKU","SKU");}
 @Test void supplierLifecycleOptimisticLockAndSecurity()throws Exception{mvc.perform(get("/api/v1/suppliers")).andExpect(status().isUnauthorized());String id=create("sup 001","Alpha").andExpect(status().isOk()).andExpect(jsonPath("$.supplierNumber").value("SUP-001")).andReturn().getResponse().getContentAsString().replaceAll(".*\"id\":\"([^\"]+)\".*","$1");mvc.perform(post("/api/v1/suppliers/"+id+"/activate").with(token()).contentType("application/json").content("{\"version\":0}")).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("ACTIVE"));mvc.perform(patch("/api/v1/suppliers/"+id).with(token()).contentType("application/json").content(supplier("OTHER","Changed",0))).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("SUPPLIER_NUMBER_IMMUTABLE"));mvc.perform(post("/api/v1/suppliers/"+id+"/block").with(token()).contentType("application/json").content("{\"version\":0}")).andExpect(status().isConflict());}
 @Test void addressesContactsProductsLookupAndPreferenceWork()throws Exception{UUID supplier=createId("SUP-A","Alpha");mvc.perform(post("/api/v1/suppliers/"+supplier+"/activate").with(token()).contentType("application/json").content("{\"version\":0}")).andExpect(status().isOk());mvc.perform(post("/api/v1/suppliers/"+supplier+"/addresses").with(token()).contentType("application/json").content("{\"type\":\"ORDERING\",\"addressLine1\":\"Street 1\",\"postalCode\":\"1010\",\"city\":\"Vienna\",\"countryCode\":\"AT\",\"version\":0}")).andExpect(status().isOk());mvc.perform(post("/api/v1/suppliers/"+supplier+"/contacts").with(token()).contentType("application/json").content("{\"firstName\":\"Ada\",\"lastName\":\"Buyer\",\"email\":\"ada@example.test\",\"role\":\"ORDERING\",\"version\":0}")).andExpect(status().isOk());String body=product(V," EXT 1 ");String response=mvc.perform(post("/api/v1/suppliers/"+supplier+"/products").with(token()).contentType("application/json").content(body)).andExpect(status().isOk()).andExpect(jsonPath("$.supplierSku").value("EXT-1")).andReturn().getResponse().getContentAsString();UUID productId=UUID.fromString(response.replaceAll(".*\"id\":\"([^\"]+)\".*","$1"));mvc.perform(post("/api/v1/supplier-products/"+productId+"/prefer").with(token()).contentType("application/json").content("{\"version\":0}")).andExpect(status().isOk()).andExpect(jsonPath("$.preferred").value(true));mvc.perform(get("/api/v1/supplier-products/lookup?supplierId="+supplier+"&supplierSku=ext-1").with(token())).andExpect(status().isOk()).andExpect(jsonPath("$.variantId").value(V.toString()));}
 @Test void databaseUniquenessAndTenantVariantForeignKeysHold()throws Exception{create(" SUP-X ","One").andExpect(status().isOk());create("sup-x","Two").andExpect(status().isConflict());UUID supplier=createId("SUP-Y","Y");UUID foreign=UUID.randomUUID();mvc.perform(post("/api/v1/suppliers/"+supplier+"/products").with(token()).contentType("application/json").content(product(foreign,"F"))).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("INVALID_SUPPLIER_PRODUCT_VARIANT"));}
 @Test void concurrentNormalizedSupplierNumberHasOneWinner()throws Exception{ExecutorService pool=Executors.newFixedThreadPool(8);try{List<Future<Integer>>calls=new ArrayList<>();for(int i=0;i<8;i++){int n=i;calls.add(pool.submit(()->create(" dup 1 ","Supplier "+n).andReturn().getResponse().getStatus()));}int ok=0;for(var f:calls)if(f.get()==200)ok++;assertEquals(1,ok);assertEquals(1,db.queryForObject("SELECT count(*) FROM suppliers",Integer.class));}finally{pool.shutdownNow();}}
 private UUID createId(String number,String name)throws Exception{return UUID.fromString(create(number,name).andExpect(status().isOk()).andReturn().getResponse().getContentAsString().replaceAll(".*\"id\":\"([^\"]+)\".*","$1"));}private ResultActions create(String number,String name)throws Exception{return mvc.perform(post("/api/v1/suppliers").with(token()).contentType("application/json").content(supplier(number,name,0)));}private String supplier(String number,String name,long version){return "{\"supplierNumber\":\""+number+"\",\"name\":\""+name+"\",\"defaultCurrency\":\"EUR\",\"paymentTermsDays\":30,\"defaultLeadTimeDays\":5,\"version\":"+version+"}";}private String product(UUID variant,String sku){return "{\"variantId\":\""+variant+"\",\"supplierSku\":\""+sku+"\",\"purchaseUnitCode\":\"BOX\",\"baseUnitsPerPurchaseUnit\":\"20\",\"minimumOrderQuantity\":\"5\",\"orderMultiple\":\"5\",\"unitCost\":\"4.123456\",\"currency\":\"EUR\",\"leadTimeDays\":7,\"version\":0}";}private org.springframework.test.web.servlet.request.RequestPostProcessor token(){return jwt().jwt(j->j.subject("admin").claim("tenant_id",T.toString()));}}
